    private static let blobA: Data = Data(base64Encoded: b64A)!
    private static let blobB: Data = Data(base64Encoded: b64B)!
    static func verts(_ name: String, nv: Int) -> [Float]? {
        guard let e = entries.first(where: { $0.name == name }) else { return nil }
        let blob = e.src == 0 ? blobA : blobB
        guard blob.count >= e.off + nv * 6 else { return nil }
        var out = [Float](repeating: 0, count: nv * 3)
        blob.withUnsafeBytes { ptr in
            let q = ptr.baseAddress!.advanced(by: e.off).assumingMemoryBound(to: UInt16.self)
            for i in 0..<nv {
                out[i*3+0] = e.min.x + Float(q[i*3+0]) / 65535.0 * e.span.x
                out[i*3+1] = e.min.y + Float(q[i*3+1]) / 65535.0 * e.span.y
                out[i*3+2] = e.min.z + Float(q[i*3+2]) / 65535.0 * e.span.z
            }
        }
        return out
    }
